def partitionPairMap (B : ι → Set Γ) (φ : ∀ i, B i × ℕ ≃ ℕ) :
    ι × ℕ → Γ × ℕ := fun z => ((φ z.1).symm z.2).1.val |> fun γ =>
      (γ, ((φ z.1).symm z.2).2)

